pygments.lexers._mysql_builtins.parse_le:
def parse_lex_functions(f):
    """Parse MySQL function names from lex.h."""
    results = set()
    for m in re.finditer('{SYM_FN?\\("(?P<function>[a-z0-9_]+)",', f, flags=re.I):
        results.add(m.group('function').lower())
    if not results:
        raise ValueError('No lex functions found')
    return results

pygments.lexers.configs._rx_indent:
def _rx_indent(level):
    tab_width = 8
    if tab_width == 2:
        space_repeat = '+'
    else:
        space_repeat = '{1,%d}' % (tab_width - 1)
    if level == 1:
        level_repeat = ''
    else:
        level_repeat = f'{{{level}}}'
    return f'(?:\\t| {space_repeat}\\t| {{{tab_width}}}){level_repeat}.*\\n'

